5|
6|import type * as vscode from 'vscode';
7|
8|/**
9| * Map panda engine events to Chat markdown progress.
10| */
11|export class StreamMapper {
12|	private lastStatus = '';
13|	private streamedAssistant = false;
14|
15|	constructor(private readonly stream: vscode.ChatResponseStream) { }
16|
17|	handle(event: string, data: unknown): void {
18|		const d = (data && typeof data === 'object') ? data as Record<string, unknown> : {};
19|
20|		switch (event) {
21|			case 'panda_stream': {
22|				// Engine: { kind: 'text'|'thinking', chunk }
23|				const kind = typeof d.kind === 'string' ? d.kind : 'text';
24|				const delta = typeof d.chunk === 'string' ? d.chunk
25|					: typeof d.delta === 'string' ? d.delta
26|						: typeof d.text === 'string' ? d.text
27|							: typeof d.content === 'string' ? d.content
28|								: '';
29|				if (delta && kind !== 'thinking') {
30|					this.stream.markdown(delta);
31|					this.streamedAssistant = true;
32|				}
33|				break;
34|			}
35|			case 'panda_stream_end': {
36|				const kind = typeof d.kind === 'string' ? d.kind : 'text';
37|				const content = typeof d.content === 'string' ? d.content : '';
38|				if (kind === 'text' && content && !this.streamedAssistant) {
39|					this.stream.markdown(content);
40|					this.streamedAssistant = true;
41|				}
42|				break;
43|			}
44|			case 'panda_block': {
45|				const type = typeof d.type === 'string' ? d.type : '';
46|				const content = typeof d.content === 'string' ? d.content : '';
47|				if (!content) {
48|					break;
49|				}
50|				if (type === 'assistant_text') {
51|					if (!this.streamedAssistant) {
52|						this.stream.markdown(content);
53|						this.streamedAssistant = true;
54|					} else {
55|						// Prefer stream deltas; avoid duplicating full blocks when streaming already happened
56|						this.stream.markdown('\n\n' + content);
57|					}
58|				} else if (type === 'tool_call' || type === 'tool') {
59|					const name = typeof d.name === 'string' ? d.name : (typeof d.tool === 'string' ? d.tool : 'tool');
60|					this.stream.markdown(`\n\n- **Tool** \`${name}\`${content ? `: ${truncate(content, 240)}` : ''}\n`);
61|				} else if (type === 'system') {
62|					this.stream.markdown(`\n\n_${escapeMd(truncate(content, 300))}_\n`);
63|				}
64|				break;
65|			}
66|			case 'panda_status': {
67|				const msg = typeof d.message === 'string' ? d.message
68|					: typeof d.status === 'string' ? d.status
69|						: typeof d.text === 'string' ? d.text
70|							: '';
71|				if (msg && msg !== this.lastStatus) {
72|					this.lastStatus = msg;
73|					this.stream.markdown(`\n\n_${escapeMd(truncate(msg, 200))}_\n`);
74|				}
75|				break;
76|			}
77|			case 'panda_tool_start': {
78|				const name = typeof d.name === 'string' ? d.name : 'tool';
79|				this.stream.markdown(`\n\n- Running \`${name}\`…\n`);
80|				break;
81|			}
82|			case 'panda_tool_end': {
83|				const name = typeof d.name === 'string' ? d.name : 'tool';
84|				const ok = d.ok !== false;
85|				this.stream.markdown(`\n- \`${name}\` ${ok ? 'done' : 'failed'}\n`);
86|				break;
87|			}
88|			case 'panda_diag': {
89|				// Quiet: ignore verbose diag unless useful later
90|				break;
91|			}
92|			default:
93|				break;
94|		}
95|	}
96|}
