98|function truncate(s: string, n: number): string {
99|	const t = s.replace(/\s+/g, ' ').trim();
100|	return t.length > n ? t.slice(0, n - 1) + '…' : t;
101|}
102|
103|function escapeMd(s: string): string {
104|	return s.replace(/([\\`*_[\]{}()#+-.!])/g, '\\$1');
105|}
